package vn.vinhkhang.warehouse;
import java.util.*;import java.math.BigDecimal;import java.time.LocalDate;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/supplier-returns") public class SupplierReturns {
 final Api core;final JdbcTemplate db;public SupplierReturns(Api core,JdbcTemplate db){this.core=core;this.db=db;}
 @PostMapping @Transactional public Object create(@RequestHeader("Authorization") String token,@RequestBody Map<String,Object> m){core.num(m,"return_source_id");core.str(m,"note");var result=core.document(token,m);core.post(token,((Number)result.get("id")).longValue());return result;}
 @GetMapping("/source/{id}") @Transactional public Object source(@RequestHeader("Authorization") String token,@PathVariable long id){core.user(token,false);var rows=db.queryForList("SELECT * FROM stock_documents WHERE id=? AND deleted=FALSE AND type='IN' AND status='POSTED'",id);if(rows.isEmpty())throw new Api.Problem(404,"Không tìm thấy lô nhập");var source=new LinkedHashMap<>(rows.getFirst());var lines=db.queryForList("SELECT l.*,p.name part_name,(SELECT COALESCE(SUM(x.quantity),0) FROM stock_document_lines x JOIN stock_documents d ON d.id=x.document_id WHERE d.return_source_id=? AND d.deleted=FALSE AND d.status='POSTED' AND x.part_id=l.part_id) returned_quantity FROM stock_document_lines l JOIN parts p ON p.id=l.part_id WHERE l.document_id=? ORDER BY l.part_id",id,id);for(var l:lines)l.put("PART_CODE",PartColors.displayCode(db,((Number)l.get("PART_ID")).longValue()));source.put("lines",lines);return source;}
 static Map<String,Object> prepare(Api core,JdbcTemplate db,Map<String,Object> raw,Long target){
  long source=core.num(raw,"return_source_id");var sources=db.queryForList("SELECT * FROM stock_documents WHERE id=? AND deleted=FALSE AND type='IN' AND status='POSTED' FOR UPDATE",source);if(sources.isEmpty())throw new Api.Problem(409,"Chọn phiếu nhập đã ghi sổ, đang tồn tại");var original=sources.getFirst();
  long supplier=original.get("SUPPLIER_ID")==null?core.num(raw,"supplier_id"):((Number)original.get("SUPPLIER_ID")).longValue();core.active("suppliers",supplier);
  String date=core.str(raw,"return_date");try{LocalDate.parse(date);}catch(Exception e){throw new Api.Problem(400,"Ngày trả không hợp lệ");}
  var result=new LinkedHashMap<>(raw);result.put("type","OUT");result.put("sales_purpose","INTERNAL");result.put("supplier_id",supplier);result.put("return_source_id",source);result.put("return_date",date);
  var lines=new ArrayList<Map<String,Object>>();var seen=new HashSet<Long>();
  for(var row:core.lines(raw,"lines")){long part=core.num(row,"part_id");core.active("parts",part);if(!seen.add(part))throw new Api.Problem(400,"Linh kiện bị chọn trùng");BigDecimal qty=core.dec(row,"quantity");var originalLines=db.queryForList("SELECT * FROM stock_document_lines WHERE document_id=? AND part_id=?",source,part);if(originalLines.isEmpty())throw new Api.Problem(400,"Linh kiện không thuộc lô nhập đã chọn");var l=originalLines.getFirst();BigDecimal returned=db.queryForObject("SELECT COALESCE(SUM(l.quantity),0) FROM stock_document_lines l JOIN stock_documents d ON d.id=l.document_id WHERE d.return_source_id=? AND l.part_id=? AND d.deleted=FALSE AND d.status='POSTED' AND d.id<>?",BigDecimal.class,source,part,target==null?-1:target);if(qty.add(returned).compareTo((BigDecimal)l.get("QUANTITY"))>0)throw new Api.Problem(409,"Số trả vượt lượng đã nhập trừ các lần trả trước");var line=new LinkedHashMap<String,Object>();line.put("part_id",part);line.put("quantity",qty);line.put("unit_cost",l.get("UNIT_COST"));line.put("color_model_id",l.get("COLOR_MODEL_ID"));lines.add(line);
  }result.put("lines",lines);return result;
 }
 static void persist(JdbcTemplate db,long id,Map<String,Object> m){if(m.get("return_source_id")!=null)db.update("UPDATE stock_documents SET return_source_id=?,return_date=?,supplier_id=?,sales_purpose='INTERNAL' WHERE id=?",m.get("return_source_id"),m.get("return_date"),m.get("supplier_id"),id);}
 static void validate(Api core,JdbcTemplate db,Map<String,Object> header,long id){if(header.get("RETURN_SOURCE_ID")==null)return;var m=new LinkedHashMap<String,Object>();m.put("return_source_id",header.get("RETURN_SOURCE_ID"));m.put("supplier_id",header.get("SUPPLIER_ID"));m.put("return_date",header.get("RETURN_DATE").toString());var lines=new ArrayList<Map<String,Object>>();for(var l:db.queryForList("SELECT * FROM stock_document_lines WHERE document_id=?",id)){var x=new LinkedHashMap<String,Object>();x.put("part_id",l.get("PART_ID"));x.put("quantity",l.get("QUANTITY"));lines.add(x);}m.put("lines",lines);prepare(core,db,m,id);}
}
